def get_html():
    return base64.b64decode(_HTML_B64).decode("utf-8")


class Api:
    """웹페이지(JS)에서 window.pywebview.api.save_file(...) 로 호출하는 네이티브 저장 기능"""

    def __init__(self):
        self.window = None

    def save_file(self, filename, content):
        if self.window is None:
            return False
        try:
            default_dir = os.path.join(os.path.expanduser("~"), "Downloads")
            if not os.path.isdir(default_dir):
                default_dir = os.path.expanduser("~")

            result = self.window.create_file_dialog(
                webview.FileDialog.SAVE,
                directory=default_dir,
                save_filename=filename,
                file_types=("JSON 파일 (*.json)", "모든 파일 (*.*)"),
            )
            if not result:
                return False  # 사용자가 취소함

            path = result if isinstance(result, str) else result[0]
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
            return True
        except Exception:
            return False


if __name__ == "__main__":
    # pywebview 최신 WinForms/Chromium 조합에서는 debug=True가 UI 스레드 밖의 WebView2
    # 속성 조회를 반복해 초기 창이 멈출 수 있다. 저장 API는 debug=False에서도 동작한다.
    webview.settings["OPEN_DEVTOOLS_IN_DEBUG"] = False

    api = Api()
    window = webview.create_window(
        "밀폐공간 환기량 산정 · 송배풍기 매칭 도구",
        html=get_html(),
        width=1200,
        height=900,
        min_size=(480, 640),
        js_api=api,
    )
    api.window = window
    webview.start(debug=False)
